// Rasterized from the security-camera SVG. These exact bytes are served to players and sent to Gemma.
export const SECURITY_IMAGE = {"mimeType":"image/png","data":""};

export function evidenceImages(context) {
  return (context.players || []).filter(p => p.evidence?.kind === 'image').map(p => {
    if (!['/evidence/pod-b.svg', '/evidence/pod-b.png'].includes(p.evidence.imageUrl)) {
      throw Object.assign(new Error('Unsupported evidence image'), { status: 422 });
    }
    return { playerId: p.id || p.playerId, ...SECURITY_IMAGE };
  });
}
